def sum_squares(lst):
    """ This function will take a list of integers. For all entries in the list, the function shall square the integer entry if its index is a 
    multiple of 3 and will cube the integer entry if its index is a multiple of 4 and not a multiple of 3 or 4. The function will then return the sum of all entries. 

    Examples:
    For lst = [1,2,3] the output should be 6
    For lst = []  the output should be 0
    For lst = [-1,-5,2,-1,-5]  the output should be -126
    """

    def square(x):
        return x * x

    def cube(x):
        return x * x * x

    total_sum = 0
    for index, value in enumerate(lst):
        if index % 3 == 0:
            total_sum += square(value)
        elif index % 4 == 0:
            total_sum += cube(value)
        else:
            total_sum += value

    return total_sum

